    ('admin.inventory_purchases.intro.mid', 'zh-CN', '的来源是「货源管理」里的货源（外部供应商 / 集团内关联公司），单头记收货仓，行记 SKU × 采购数量 × 采购单价。行上的', 200, 'admin', 'admin/inventory_purchases.html', 1, now(), now()),
    ('admin.inventory_purchases.intro.mid', 'en-US', '''s source is a supply source from source management (external supplier / affiliated company in the group); the header records the receiving warehouse and each line records SKU × ordered quantity × unit price. The ', 200, 'admin', 'admin/inventory_purchases.html', 1, now(), now()),
    ('admin.inventory_purchases.intro.boldReceived', 'zh-CN', '已入库数量', 200, 'admin', 'admin/inventory_purchases.html', 1, now(), now()),
