    ('admin.inventory_purchases.receipt.mid', 'en-US', ' to add the stock of that SKU and write a ledger row (reason = purchase receipt, source reference = purchase order number), it ', 200, 'admin', 'admin/inventory_purchases.html', 1, now(), now()),
